import{_ as a,o,c as r,a2 as n}from"./chunks/framework.D0_YsCyK.js";const p=JSON.parse('{"title":"监控","description":"","frontmatter":{},"headers":[],"relativePath":"guide/monitoring.md","filePath":"guide/monitoring.md","lastUpdated":1792725675000}'),e={name:"guide/monitoring.md"};function i(s,t,l,g,d,h){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="监控" tabindex="-1">监控 <a class="header-anchor" href="#监控" aria-label="Permalink to &quot;监控&quot;">​</a></h1><p>监控分三类：节点监控、服务监控、隧道质量。入口按角色分开：</p><ul><li><strong>管理员</strong>没有独立的「监控」菜单——从 <strong>节点</strong> 页逐个节点打开监控（实时指标、历史曲线、该节点的服务监控），隧道质量从 <strong>中转</strong> 页的 <strong>质量</strong> 标签看；直接访问 <code>/monitor</code> 会跳回节点页。</li><li><strong>被授予监控权限的普通用户</strong>有独立的 <strong>监控</strong> 总览页，跨节点看状态（见下「监控权限」）。</li></ul><p>本文只讲监控面本身；哪些异常会经 <a href="./notify">通知</a> 推送，以通知页的事件清单为准。</p><h2 id="节点监控" tabindex="-1">节点监控 <a class="header-anchor" href="#节点监控" aria-label="Permalink to &quot;节点监控&quot;">​</a></h2><p>按节点列出在线状态与运行指标（连接状态、版本、流量与资源占用等）。管理员在节点列表里点开单个节点的监控看明细；普通用户在总览页跨节点扫一遍有没有异常。</p><h2 id="服务监控" tabindex="-1">服务监控 <a class="header-anchor" href="#服务监控" aria-label="Permalink to &quot;服务监控&quot;">​</a></h2><p>对任意目标做定时连通性探测，适合盯落地机端口、第三方服务或某个 IP 是否可达：</p><ul><li><strong>类型</strong>：TCP（端口连通）、ICMP（ping）；</li><li><strong>经节点探测</strong>：TCP / ICMP 可以指定由某个节点上的 agent 发起探测，测的是「从该节点出发」的连通性；TCP 可不指定节点（面板侧探测）；ICMP 必须指定执行节点；</li><li><strong>间隔与超时</strong>：每项可单独设探测间隔与超时（超时最大 60 秒）；可以随时 <strong>立即执行</strong> 一次，不等下一轮；</li><li><strong>启用 / 停用</strong>：停用的探测不再执行，历史结果保留；停用只停调度，立即执行对停用项同样可用；</li><li>探测结果（成功/失败、耗时）留存并可回看。</li></ul><h2 id="隧道质量" tabindex="-1">隧道质量 <a class="header-anchor" href="#隧道质量" aria-label="Permalink to &quot;隧道质量&quot;">​</a></h2><p>逐跳探测每条隧道的连通与延迟（入口 → 中间跳 → 出口），定位多跳线路里是哪一段出问题。隧道质量探测默认开启，探测间隔在 <strong>网站配置</strong> 的监控设置里可调。</p><h2 id="监控权限" tabindex="-1">监控权限 <a class="header-anchor" href="#监控权限" aria-label="Permalink to &quot;监控权限&quot;">​</a></h2><p>管理员不需要授权，直接从节点页 / 中转页进入。普通用户默认没有监控入口：管理员在 <strong>用户</strong> 页给指定用户授予<strong>监控权限</strong>后，该用户菜单里出现 <strong>监控</strong> 总览页，能看状态，但不能改监控配置、不能执行管理操作。</p><h2 id="数据保留" tabindex="-1">数据保留 <a class="header-anchor" href="#数据保留" aria-label="Permalink to &quot;数据保留&quot;">​</a></h2><p>监控类数据（探测结果、质量样本等）的保留天数在 <strong>网站配置</strong> 里可设，过期数据自动清理。需要长期留档的指标请用每日汇总通知或自行导出。</p>',15)])])}const u=a(e,[["render",i]]);export{p as __pageData,u as default};
